"""Project-scoped precondition bindings from ``agent.yml`` ``orchestrator``."""

from __future__ import annotations

from typing import Mapping

import structlog
from pydantic import BaseModel, ConfigDict, field_validator

from rasa.mantle.skills.conditions import (
    ConditionEvaluationError,
    evaluate_expression,
)

structlogger = structlog.get_logger()

PRECONDITION_UNMET_RESPONSE = "utter_precondition_unmet"
"""Bundled response name emitted when a resolver completes without satisfying."""

PRECONDITION_UNMET_DEFAULT_TEXT = (
    "I'm sorry, I wasn't able to continue with that request."
)


class PreconditionBinding(BaseModel):
    """One semantic precondition contract bound to project memory and a resolver."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    satisfied_when: str
    resolve_with: str
    unmet_utterance: bool = True

    @field_validator("satisfied_when", "resolve_with")
    @classmethod
    def _non_empty_string(cls, value: str) -> str:
        if not isinstance(value, str) or not value.strip():
            raise ValueError("must be a non-empty string")
        return value.strip()


def precondition_satisfied(
    binding: PreconditionBinding,
    memory_values: Mapping[str, object],
) -> bool:
    """Return whether *binding*'s ``satisfied_when`` expression is true."""
    try:
        return bool(evaluate_expression(binding.satisfied_when, memory_values))
    except ConditionEvaluationError as exc:
        structlogger.debug(
            "mantle.precondition.condition_evaluation_failed",
            error=str(exc),
        )
        return False
